<?php
$title='Appointments';$subtitle='Meetings booked by leads or your team';
$me=user();$sales=role()==='sales';
$au=$sales?' AND (a.user_id='.(int)$me['id'].' OR l.assigned_to='.(int)$me['id'].' OR l.assigned_to IS NULL)':'';
if(is_post()){
  $a=$_POST['a']??'';
  try{
    if($a==='add'){
      $t=strtotime($_POST['at']??'');if(!$t)throw new Exception('Pick a date and time.');
      $lid=(int)($_POST['lead']??0);
      if($lid&&!lead_ok(DB::row('SELECT * FROM leads WHERE id=?',[$lid])))throw new Exception('Choose one of your leads.');
      if(!$lid){$n=trim($_POST['name']??'');if($n==='')throw new Exception('Choose a lead or enter a name.');$lid=CRM::create(['contact_name'=>$n,'name'=>trim($_POST['company']??'')?:$n,'phone'=>trim($_POST['phone']??''),'email'=>trim($_POST['email']??'')],'manual','Appointment');if($sales)DB::update('leads',['assigned_to'=>$me['id']],'id=?',[$lid]);}
      Booking::book($lid,$t,'admin',trim($_POST['notes']??''),trim($_POST['title']??'')?:null);flash('Appointment booked'.(GCal::ready()?' and added to Google Calendar':'').'.');}
    if($a==='fix_url'&&can('settings')){$h=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off'?'https':'http').'://'.$_SERVER['HTTP_HOST'].rtrim(str_replace('\\','/',dirname($_SERVER['SCRIPT_NAME'])),'/');Settings::set('app_url',$h);flash('App address updated – booking links now use '.e($h).'.');}
    if($a==='st'&&DB::val("SELECT a.id FROM appointments a LEFT JOIN leads l ON l.id=a.lead_id WHERE a.id=?$au",[(int)$_POST['id']]))Booking::status((int)$_POST['id'],$_POST['st']??'');
  }catch(Throwable $e){flash(e($e->getMessage()),'err');}
  back(url('appointments'));}
$m=preg_match('/^\d{4}-\d{2}$/',$_GET['m']??'')?$_GET['m']:date('Y-m');
$first=strtotime($m.'-01');$start=strtotime('monday this week',$first);if(date('N',$first)==1)$start=$first;
$end=strtotime('+41 days',$start);
$rows=DB::all("SELECT a.*,l.name,l.contact_name FROM appointments a LEFT JOIN leads l ON l.id=a.lead_id WHERE a.start_at BETWEEN ? AND ?$au ORDER BY a.start_at",[date('Y-m-d 00:00:00',$start),date('Y-m-d 23:59:59',$end)]);
$by=[];foreach($rows as $r)$by[substr($r['start_at'],0,10)][]=$r;
$up=DB::all("SELECT a.*,l.name,l.contact_name,l.phone,l.email FROM appointments a LEFT JOIN leads l ON l.id=a.lead_id WHERE a.status='scheduled' AND a.start_at>=NOW()-INTERVAL 1 HOUR$au ORDER BY a.start_at LIMIT 12");
$leads=DB::all('SELECT l.id,l.name,l.contact_name FROM leads l WHERE l.is_lead=1'.scope().' ORDER BY COALESCE(l.lead_at,l.created_at) DESC LIMIT 400');
$k=DB::row("SELECT SUM(a.status='scheduled' AND a.start_at>=NOW()) up,SUM(DATE(a.start_at)=CURDATE() AND a.status='scheduled') td,SUM(a.status='completed') dn,SUM(a.status='no_show') ns,SUM(a.booked_by='lead') sb FROM appointments a LEFT JOIN leads l ON l.id=a.lead_id WHERE 1=1$au");
$pre=(int)($_GET['lead']??0);
?>
<?php $bl=Booking::link();$host=$_SERVER['HTTP_HOST']??'';$urlOff=$host&&strcasecmp((string)parse_url(app_url(),PHP_URL_HOST),preg_replace('/:\d+$/','',$host))!==0;$td=date('Y-m-d');$grp=[];foreach($up as $x){$d=substr($x['start_at'],0,10);$grp[$d===$td?'Today':($d===date('Y-m-d',strtotime('+1 day'))?'Tomorrow':date('l, d M',strtotime($d)))][]=$x;}?>
<div class="stats"><?=kpi('Today',(int)$k['td'],'clock','orange','meetings scheduled')?><?=kpi('Upcoming',(int)$k['up'],'cal','teal','scheduled from now')?><?=kpi('Completed',(int)$k['dn'],'check','green',(int)$k['ns'].' no-shows')?><?=kpi('Self-booked',(int)$k['sb'],'link','violet','via your booking link')?></div>
<div class="g3r ap"><div class="card"><div class="card-h"><h3><span class="hi c-teal"><?=icon('clock')?></span>Next appointments</h3><button type="button" class="btn btn-p btn-sm" onclick="A.modal('m-book')"><?=icon('plus')?>Book a meeting</button></div>
<?php if(!$up):?><div class="empty sm"><?=icon('cal')?><h4>No upcoming appointments</h4><p>Share your booking link or book one for a lead.</p></div><?php endif?>
<?php foreach($grp as $gl=>$xs):?><div class="ap-g"><?=e($gl)?></div><?php foreach($xs as $a):$t=strtotime($a['start_at']);$soon=$t-time()<3600;?><div class="ap-r<?=$soon?' soon':''?>"><div class="ap-t"><b><?=date('h:i',$t)?></b><small><?=date('A',$t)?> · <?=(int)round((strtotime($a['end_at'])-$t)/60)?>m</small></div><div class="grow"><b><a href="<?=url('lead',['id'=>$a['lead_id']])?>"><?=e($a['contact_name']?:$a['name'])?></a><?=$a['booked_by']==='lead'?' <span class="bdg c-violet">self-booked</span>':''?><?=$soon&&$t>time()?' <span class="bdg c-orange">in '.max(1,(int)round(($t-time())/60)).' min</span>':''?></b><small><?=e($a['title'])?></small><small><?php if($a['phone']):?><a class="lnk" href="tel:<?=e($a['phone'])?>"><?=icon('phone','xs')?> <?=e($a['phone'])?></a><?php endif?><?php if($a['email']):?> · <?=e($a['email'])?><?php endif?><?php if($a['location']&&!$a['meet_link']):?> · <?=icon('pin','xs')?> <?=e(mb_strimwidth($a['location'],0,60,'…'))?><?php endif?></small></div><form method="post" class="ap-a"><?=csrf_field()?><input type="hidden" name="a" value="st"><input type="hidden" name="id" value="<?=$a['id']?>"><?php if($a['meet_link']):?><a class="btn btn-xs btn-g" href="<?=e($a['meet_link'])?>" target="_blank" rel="noopener"><?=icon('play')?>Join</a><?php endif?><button class="btn btn-xs" name="st" value="completed" title="Mark as held"><?=icon('check')?>Done</button><button class="btn btn-xs" name="st" value="no_show">No-show</button><button class="btn btn-xs" name="st" value="cancelled" onclick="return confirm('Cancel this appointment?')">Cancel</button></form></div><?php endforeach;endforeach?></div>
<div class="col"><div class="card"><div class="card-h"><h3><span class="hi c-violet"><?=icon('link')?></span>Your booking link</h3></div><?php if($urlOff&&can('settings')):?><div class="al al-warn"><?=icon('alert')?><span>Links use <b><?=e(app_url()?:'—')?></b> but you opened Setu at <b><?=e($host)?></b>.<form method="post" style="margin-top:6px"><?=csrf_field()?><input type="hidden" name="a" value="fix_url"><button class="btn btn-sm"><?=icon('refresh')?>Use this address</button></form></span></div><?php endif?><div class="copy"><input readonly value="<?=e($bl)?>"><button type="button" class="btn btn-sm" data-copy="<?=e($bl)?>" title="Copy"><?=icon('copy')?></button><a class="btn btn-sm" href="<?=e($bl)?>" target="_blank" title="Preview"><?=icon('eye')?></a></div><p class="hint">Free slots follow your working hours<?=GCal::ready()?' and Google Calendar':''?>. Every lead also has a personal link – use <code>{{booking_link}}</code> in messages.<?php if(can('settings')):?> <a class="lnk" href="<?=url('settings',['tab'=>'appointments'])?>">Hours &amp; reminders</a> · <a class="lnk" href="<?=url('settings',['tab'=>'company'])?>">App address</a><?php endif?></p></div>
<div class="card"><div class="card-h"><h3><span class="hi c-amber"><?=icon('sliders')?></span>Setup</h3></div><div class="li"><span class="grow"><b>Hours</b><small><?=e(setting('appt_start','10:00'))?>–<?=e(setting('appt_end','18:00'))?> · <?=(int)setting('appt_slot','30')?> min slots</small></span></div><div class="li"><span class="grow"><b>Reminders</b><small><?=setting('appt_remind')==='1'?'1 hour before':'off'?> · <?=setting('appt_notify')==='1'?'email me on booking':'no booking email'?></small></span></div><div class="li" style="border:0"><span class="grow"><b>Google Calendar</b><small><?=GCal::ready()?'Connected':'Not connected'?></small></span></div></div></div></div>
<div class="card"><div class="card-h"><h3><span class="hi c-indigo"><?=icon('cal')?></span><?=e(date('F Y',$first))?></h3><div class="row"><a class="ib bd" href="<?=url('appointments',['m'=>date('Y-m',strtotime('-1 month',$first))])?>" title="Previous month">‹</a><a class="btn btn-sm" href="<?=url('appointments')?>">Today</a><a class="ib bd" href="<?=url('appointments',['m'=>date('Y-m',strtotime('+1 month',$first))])?>" title="Next month">›</a></div></div><div class="cal"><?php foreach(['Mon','Tue','Wed','Thu','Fri','Sat','Sun'] as $dn):?><div class="ch"><?=$dn?></div><?php endforeach?><?php for($d=$start;$d<=$end;$d=strtotime('+1 day',$d)):$ds=date('Y-m-d',$d);?><div class="<?=date('Y-m',$d)!==$m?'out':''?> <?=$ds===$td?'td':''?>"><span class="dn"><?=date('j',$d)?></span><?php foreach($by[$ds]??[] as $a):?><a class="ev <?=$a['status']==='completed'?'done':(in_array($a['status'],['cancelled','no_show'],true)?'cx':'')?>" href="<?=url('lead',['id'=>$a['lead_id']])?>" title="<?=e($a['title'])?>"><?=date('H:i',strtotime($a['start_at']))?> <?=e($a['contact_name']?:$a['name'])?></a><?php endforeach?></div><?php endfor?></div></div>
<div class="md" id="m-book" onclick="if(event.target===this)A.close()"><form method="post" class="md-b" id="book"><?=csrf_field()?><input type="hidden" name="a" value="add"><div class="md-h"><h3><span class="hi c-teal"><?=icon('plus')?></span>Book a meeting</h3><button type="button" class="ib" onclick="A.close()"><?=icon('x')?></button></div><label>Lead<select name="lead" data-toggle><option value="">— New person —</option><?php foreach($leads as $x):?><option value="<?=$x['id']?>" <?=$pre===(int)$x['id']?'selected':''?>><?=e($x['contact_name']?:$x['name'])?></option><?php endforeach?></select></label><div class="fg" data-show="lead="><label>Name<input name="name"></label><label>Phone<input name="phone" type="tel"></label><label>Email<input name="email" type="email"></label><label>Business<input name="company"></label></div><label>Date &amp; time<input type="datetime-local" name="at" required min="<?=date('Y-m-d\TH:i')?>"></label><label>Title<input name="title" placeholder="<?=e(setting('appt_title','Meeting'))?>"></label><label class="mb0">Notes<textarea name="notes" rows="2"></textarea></label><div class="card-f"><button class="btn btn-p"><?=icon('check')?>Book meeting</button><span class="muted xs"><?=(int)setting('appt_slot','30')?> min<?=GCal::ready()?' · added to Google Calendar':''?> · confirmation by email</span></div></form></div>
<?php if(isset($_GET['add'])||$pre):?><script>addEventListener('load',function(){A.modal('m-book')})</script><?php endif?>
